#include "goal1_tensor_endpoint_amplitude.hpp"
#include "goal1_native_trace_chart.hpp"
#include <iostream>
#include <iomanip>
#include <string>
#include <cstdlib>
namespace cs=cubed_sphere;namespace h=z4c::hyperboloidal;namespace tc=cs::native_trace_chart;namespace te=cs::tensor_endpoint;
Real Read(){std::string s;if(!(std::cin>>s))throw std::runtime_error("short trace chart input");char*e;Real x=std::strtod(s.c_str(),&e);if(*e||!std::isfinite(x))throw std::runtime_error("invalid chart token");return x;}
struct Endpoint{std::array<Real,22>rhs{};Real value=0,first=0,second=0;};
Endpoint Limit(const std::array<cs::Jet,22>&r,const std::array<cs::Jet,22>&s,const Real nu[3]){Endpoint out;Real norm=0;for(Real x:std::array<Real,3>{nu[0],nu[1],nu[2]})norm+=x*x;for(int n=0;n<22;++n){out.value=std::max(out.value,std::abs(s[n].f));Real q=0;if(n==7||n==17){for(int d=0;d<3;++d){out.first=std::max(out.first,std::abs(s[n].d[d]));for(int e=0;e<3;++e)q+=nu[d]*nu[e]*s[n].h[d][e]/(2*norm*norm);}for(int d=0;d<3;++d)for(int e=0;e<3;++e)out.second=std::max(out.second,std::abs(s[n].h[d][e]-2*nu[d]*nu[e]*q));}else{for(int d=0;d<3;++d)q+=nu[d]*s[n].d[d]/norm;for(int d=0;d<3;++d)out.first=std::max(out.first,std::abs(s[n].d[d]-nu[d]*q));}out.rhs[n]=r[n].f+q;}return out;}
int main(int argc,char**argv){Kokkos::initialize(argc,argv);std::cout<<std::setprecision(17);int status=0;try{while(std::cin>>std::ws,std::cin.peek()!=EOF){int id=Read(),mode=Read();Real time=Read(),x[3];for(auto&v:x)v=Read();h::Z4cJet<Real>empty{};auto u=cs::typed_support::Map<Real>(empty,[](int,Real){return Read();});Real Q=Read(),dQ[3],tau,dtau[3],target[22];for(auto&v:dQ)v=Read();tau=Read();for(auto&v:dtau)v=Read();for(auto&v:target)v=Read();h::LayerReference<Real>descriptor(1.,.5,{true,.05,.95});auto p=descriptor.At(x[0],x[1],x[2]);Real got[22]{},chain=0,pole=0,first=0,second=0,negative=0,invariance=0;
 if(mode==0||mode==2){auto con=rwm::ReferenceConnection(p,x);h::OmegaJet<Real>o{};o.omega=p.omega;for(int i=0;i<3;++i){o.gradient[i]=p.domega[i];for(int j=0;j<3;++j)o.hessian[i][j]=p.omega_hessian[i][j];}h::SetStationaryOmegaNormal(u.alpha.value,u.beta.value,u.alpha.d,u.beta.d,o);
 if(mode==2){u.theta.value=p.omega*tau;u.trace.value=p.omega*(Q-2*tau)+3*o.normal;for(int i=0;i<3;++i){u.theta.d[i]=p.domega[i]*tau+p.omega*dtau[i];u.trace.d[i]=p.domega[i]*(Q-2*tau)+p.omega*(dQ[i]-2*dtau[i])+3*o.dnormal[i];}}
 auto parts=tc::Evaluate(u,p,con,Q,tau,dQ,dtau);if(!parts.valid||!(p.omega>0))throw std::runtime_error("invalid finite chart");for(int n=0;n<22;++n)got[n]=parts.regular[n]+parts.numerator[n]/(p.omega*((n==7||n==17)?p.omega:1));auto direct=cs::typed_support::Core(u,p,con);Real wdot=-(o.normal*got[18]+p.domega[0]*got[19]+p.domega[1]*got[20]+p.domega[2]*got[21])/u.alpha.value;for(int n=0;n<22;++n){Real native=n==7?p.omega*(got[7]-2*got[17])+3*wdot:(n==17?p.omega*got[17]:got[n]);chain=std::max(chain,std::abs(native-direct[n])/std::max({Real(1),std::abs(native),std::abs(direct[n])}));}negative=std::abs((direct[7]+2*direct[17])/p.omega-got[7]);
 }else if(mode==1){auto ref=cs::native_endpoint::OuterReference(p,x);ref.omega.f=0;auto state=cs::native_endpoint::Spatial(u);cs::Jet q(Q),t(tau),dq[3],dt[3];for(int d=0;d<3;++d){q.d[d]=dQ[d];t.d[d]=dtau[d];dq[d]=cs::Jet(dQ[d]);dt[d]=cs::Jet(dtau[d]);}auto c=cs::native_endpoint::OuterConnection(x);auto parts=tc::Evaluate(state,ref,c,q,t,dq,dt);auto result=Limit(parts.regular,parts.numerator,p.domega);for(int n=0;n<22;++n)got[n]=result.rhs[n];pole=result.value;first=result.first;second=result.second;auto altered=q;for(int d=0;d<3;++d)for(int e=0;e<3;++e)altered.h[d][e]=.123*(1+d+e);auto again=tc::Evaluate(state,ref,c,altered,t,dq,dt);auto other=Limit(again.regular,again.numerator,p.domega);for(int n=0;n<22;++n)invariance=std::max(invariance,std::abs(other.rhs[n]-got[n]));auto unused=tc::Evaluate(cs::native_endpoint::Spatial(u,.123),ref,c,q,t,dq,dt);auto unused_limit=Limit(unused.regular,unused.numerator,p.domega);for(int n=0;n<22;++n)invariance=std::max(invariance,std::abs(unused_limit.rhs[n]-got[n]));for(int d=0;d<3;++d)negative=std::max(negative,std::abs(parts.numerator[7].d[d]+3*parts.sw0.d[d]));
 }else if(mode==3){auto raw=te::LinearParts(u,p,x);auto ref0=cs::native_endpoint::OuterReference(p,x);ref0.omega.f=0;auto ref=cs::typed_support::Constant<te::D>(p);ref.omega=te::D(ref0.omega);ref.alpha=te::D(ref0.alpha);ref.L=te::D(ref0.L);ref.state=cs::typed_support::Map<te::D>(ref0.state,[](int,cs::Jet q){return te::D(q);});for(int i=0;i<3;++i){ref.beta[i]=te::D(ref0.beta[i]);ref.domega[i]=te::D(ref0.domega[i]);ref.dalpha[i]=te::D(ref0.dalpha[i]);for(int j=0;j<3;++j)ref.omega_hessian[i][j]=te::D(ref0.omega_hessian[i][j]);}auto c0=cs::native_endpoint::OuterConnection(x);rwm::Connection<te::D>c{};c.valid=true;for(int a=0;a<4;++a)for(int i=0;i<3;++i)for(int j=0;j<3;++j)c.scaled[a][i][j]=te::D(c0.scaled[a][i][j]);cs::Jet q0=cs::Jet(-6)/ref0.alpha,delta(Q);te::D dq[3],dt[3];for(int d=0;d<3;++d){delta.d[d]=dQ[d];dq[d]=te::D(cs::Jet(q0.d[d]),cs::Jet(dQ[d]));dt[d]=te::D(cs::Jet(0),cs::Jet(dtau[d]));}te::D q(q0,delta),t(cs::Jet(0),cs::Jet(tau));for(int d=0;d<3;++d)t.a.d[d]=dtau[d];auto parts=tc::Evaluate(raw.state,ref,c,q,t,dq,dt);std::array<cs::Jet,22>r,s;for(int n=0;n<22;++n){r[n]=parts.regular[n].a;s[n]=parts.numerator[n].a;}auto result=Limit(r,s,p.domega);for(int n=0;n<22;++n)got[n]=result.rhs[n];pole=result.value;first=result.first;second=result.second;auto qchanged=q;for(int d=0;d<3;++d)for(int e=0;e<3;++e)qchanged.a.h[d][e]=.123*(1+d+e);auto unused=tc::Evaluate(te::LinearParts(u,p,x,.123).state,ref,c,qchanged,t,dq,dt);for(int n=0;n<22;++n){r[n]=unused.regular[n].a;s[n]=unused.numerator[n].a;}auto unused_limit=Limit(r,s,p.domega);for(int n=0;n<22;++n)invariance=std::max(invariance,std::abs(unused_limit.rhs[n]-got[n]));for(int d=0;d<3;++d)negative=std::max(negative,std::abs(s[7].d[d]+3*parts.sw0.a.d[d]));
 }else throw std::runtime_error("unknown chart test mode");Real error=0;if(mode!=2)for(int n=0;n<22;++n)error=std::max(error,std::abs(got[n]-target[n])/std::max({Real(1),std::abs(got[n]),std::abs(target[n])}));std::cout<<"{\"id\":"<<id<<",\"mode\":"<<mode<<",\"native22_chain_scaled\":"<<chain<<",\"oracle22_scaled\":"<<error<<",\"numerator_value\":"<<pole<<",\"numerator_first_compatibility\":"<<first<<",\"scalar_second_compatibility\":"<<second<<",\"unprovided_Q_second_invariance\":"<<invariance<<",\"negative_omit_w_time\":"<<negative<<",\"Q_time\":"<<got[7]<<",\"tau_time\":"<<got[17]<<"}\n";}}catch(const std::exception&e){std::cerr<<e.what()<<'\n';status=1;}Kokkos::finalize();return status;}
